void validateRegistry(List<WidgetSpec> widgets,List<ViewportSpec> views){if(views.isEmpty||views.length>8||widgets.length>60||widgets.map((w)=>w.id).toSet().length!=widgets.length||views.map((v)=>v.id).toSet().length!=views.length||views.map((v)=>v.minWidth).toSet().length!=views.length||!views.any((v)=>v.minWidth==0))throw ArgumentError('invalid_registry');for(final v in views){ViewportSpec.fromJson(v.toJson());}for(final w in widgets){WidgetSpec.fromJson(w.toJson());if(w.views.any((v)=>!views.any((c)=>c.id==v&&c.columns>=w.minSpan)))throw ArgumentError('invalid_widget_view');}}
class Placement {final String id;final int span,rows;const Placement(this.id,this.span,this.rows);Map<String,Object?> toJson()=>{'id':id,'span':span,'rows':rows};}
