DashboardLayout parseDashboard(String text,List<WidgetSpec> widgets,List<ViewportSpec> views){if(utf8.encode(text).length>65536)throw ArgumentError('layout_too_large');return DashboardLayout.fromJson(jsonDecode(text),widgets,views);}
String activeViewport(double width,List<ViewportSpec> views){if(!width.isFinite||width<0||views.isEmpty)throw ArgumentError('invalid_viewport');final sorted=[...views]..sort((a,b)=>a.minWidth.compareTo(b.minWidth));return sorted.lastWhere((v)=>width>=v.minWidth,orElse:()=>sorted.first).id;}
